#' Summarize repeated connectivity events by source
summarize_connectivity_by_source <- function(exchange) {
  if (!nrow(exchange)) return(data.frame()); candidate <- exchange[exchange$within_evaluation_distance, ]; groups <- split(candidate, candidate$source_id)
  sm <- function(x) if (all(is.na(x))) NA_real_ else mean(x, na.rm = TRUE); ss <- function(x) if (all(is.na(x))) NA_real_ else sum(x, na.rm = TRUE)
  do.call(rbind, lapply(groups, function(x) { per_run <- tapply(x$intercept, x$run_id, sum); data.frame(source_id = x$source_id[1], n_runs = length(unique(x$run_id)), n_unique_receptors = length(unique(x$receptor_id)), n_candidate_receptors = length(unique(x$receptor_id)), n_intercepted_receptors = length(unique(x$receptor_id[x$intercept])), total_intercept_events = sum(x$intercept), intercept_rate_per_candidate_run = sum(x$intercept) / nrow(x), mean_receptors_intercepted_per_run = mean(per_run), maximum_receptors_intercepted_per_run = max(per_run), mean_first_arrival_hours = sm(x$first_arrival_hour[x$intercept]), mean_particle_count_cumulative = sm(x$particle_count_cumulative), total_particle_count_cumulative = ss(x$particle_count_cumulative), total_decayed_mass_cumulative = ss(x$decayed_mass_cumulative), total_decayed_concentration_hourly_sum = ss(x$decayed_concentration_hourly_sum), first_release_start = min(x$release_start), last_release_start = max(x$release_start), stringsAsFactors = FALSE) }))
}
